import numpy as np
t=df['t'].values;P=df['P'].values;y=df['dP_dt'].values
Ps=[P**i for i in range(5)]
tfs={'t':t,'t2':t**2,'log':np.log(t),'sqrt':np.sqrt(t),'exp-t':np.exp(-t),'1/t':1/t,'exp-t/3':np.exp(-t/3),'exp+t/10':np.exp(t/10)}
names=list(tfs)
for combo in [['t'],['t','t2'],['t','log'],['t','sqrt'],['t','exp-t'],['t','1/t'],['t','exp-t/3'],['t','exp+t/10'],['t','log','t2'],['t','exp-t','t2']]:
    cols=[]
    for n in ['1']+combo:
        f=np.ones_like(t) if n=='1' else tfs[n]
        for g in Ps: cols.append(f*g)
    # plus t*P^k interaction already included by combo
    A=np.column_stack(cols); c,*_=np.linalg.lstsq(A,y,rcond=None); r=y-A@c
    print(combo,'%.3e'%(np.mean(r**2)/np.var(y)))
